import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#world');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x80b5b8);scene.fog=new THREE.FogExp2(0x80b5b8,.0068);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,700);camera.position.set(0,14,25);
scene.add(new THREE.HemisphereLight(0xc9ebdf,0x263e39,2.0));
const sun=new THREE.DirectionalLight(0xffe6b5,3.2);sun.position.set(-35,55,18);scene.add(sun);
const fill=new THREE.DirectionalLight(0x8dbbc7,1.05);fill.position.set(25,20,-30);scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const oceanMat=new THREE.MeshStandardMaterial({color:0x176679,roughness:.36,metalness:.18,flatShading:true});
const oceanGeom=new THREE.PlaneGeometry(900,900,100,100);oceanGeom.rotateX(-Math.PI/2);
const ocean=new THREE.Mesh(oceanGeom,oceanMat);ocean.position.y=-.32;scene.add(ocean);
const wavePos=oceanGeom.attributes.position;const waveBase=Float32Array.from(wavePos.array);
const world=new THREE.Group();scene.add(world);
const islandPositions=[[-28,-36],[43,-49],[67,25],[-57,56],[8,-95]];
function makeIsland(x,z,scale=1,name='Port Royal'){
 const group=new THREE.Group();group.position.set(x,0,z);group.scale.setScalar(scale);world.add(group);
 const sand=new THREE.Mesh(new THREE.CylinderGeometry(11,14,2.6,9,1),mat(0xc6ad78));sand.position.y=.12;group.add(sand);
 const land=new THREE.Mesh(new THREE.ConeGeometry(13,9,8),mat(0x48664a));land.position.y=4.2;group.add(land);
 const rock=new THREE.Mesh(new THREE.ConeGeometry(7,7,7),mat(0x5d7451));rock.position.set(-4,6,0);group.add(rock);
 for(let i=0;i<8;i++){const tree=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13,.21,2.1,5),mat(0x684933));trunk.position.y=1;tree.add(trunk);const leaves=new THREE.Mesh(new THREE.ConeGeometry(.9,2.7,6),mat(i%2?0x315e45:0x426b4c));leaves.position.y=2.65;tree.add(leaves);tree.position.set((Math.random()-.5)*16,1.25,(Math.random()-.5)*15);group.add(tree)}
 const dock=new THREE.Mesh(new THREE.BoxGeometry(6,.3,12),mat(0x71583d));dock.position.set(5,.25,12);group.add(dock);
 const flagpole=new THREE.Mesh(new THREE.CylinderGeometry(.08,.1,9,6),mat(0xd0c3a2));flagpole.position.set(5,6,13);group.add(flagpole);const flag=new THREE.Mesh(new THREE.PlaneGeometry(2.4,1.15),new THREE.MeshStandardMaterial({color:0xb34a35,side:THREE.DoubleSide}));flag.position.set(6.1,9.3,13);group.add(flag);
 group.userData={name,group};return group
}
const islands=islandPositions.map((p,i)=>makeIsland(...p,i===0?1.15:.85,['Port Royal','Cinder Cay','Fort Nassau','Mariner’s Rest','Saint Elmo'][i]));
function makeShip({color=0x5e3d2c,sail=0xe6dfc7,enemy=false,type='brigantine'}={}){
 const g=new THREE.Group();const wood=mat(color),trim=mat(0xb59054,.58),dark=mat(0x362b25),cloth=new THREE.MeshStandardMaterial({color:sail,side:THREE.DoubleSide,roughness:.9});
 const hull=new THREE.Mesh(new THREE.CylinderGeometry(.3,1.05,9,8,1),wood);hull.rotation.z=Math.PI/2;hull.scale.set(1,1,.75);hull.position.y=.3;g.add(hull);
 const deck=new THREE.Mesh(new THREE.BoxGeometry(7,.42,2.7),wood);deck.position.y=.72;g.add(deck);
 const bow=new THREE.Mesh(new THREE.ConeGeometry(.95,2.3,5),wood);bow.rotation.z=-Math.PI/2;bow.position.set(4.65,.35,0);g.add(bow);
 const stern=new THREE.Mesh(new THREE.BoxGeometry(1.3,1.2,2.65),wood);stern.position.set(-3.65,1,0);g.add(stern);
 const rail=new THREE.Mesh(new THREE.BoxGeometry(6.6,.24,2.95),trim);rail.position.set(-.05,1.03,0);g.add(rail);
 const masts=type==='sloop'?[-.3]:[-2,1.4];masts.forEach((x,i)=>{const h=type==='sloop'?8:10-(i*1.3);const mast=new THREE.Mesh(new THREE.CylinderGeometry(.12,.2,h,7),dark);mast.position.set(x,h/2+1,0);g.add(mast);const yard=new THREE.Mesh(new THREE.CylinderGeometry(.08,.11,5.1,6),dark);yard.rotation.x=Math.PI/2;yard.position.set(x,h*.75+1,0);g.add(yard);const sailMesh=new THREE.Mesh(new THREE.PlaneGeometry(3.9,h*.53),cloth);sailMesh.position.set(x,h*.48+1,0);sailMesh.rotation.y=Math.PI/2;g.add(sailMesh);const flag=new THREE.Mesh(new THREE.PlaneGeometry(1.4,.62),new THREE.MeshStandardMaterial({color:enemy?0x9a3530:0xc99c50,side:THREE.DoubleSide}));flag.position.set(x,h+1.1,0);g.add(flag)});
 for(const side of [-1,1])for(let i=0;i<(type==='sloop'?2:3);i++){const cannon=new THREE.Mesh(new THREE.CylinderGeometry(.12,.14,.8,8),dark);cannon.rotation.x=Math.PI/2;cannon.position.set(-2.2+i*2,1.05,side*1.52);g.add(cannon);const wheel=new THREE.Mesh(new THREE.TorusGeometry(.24,.055,5,12),trim);wheel.position.set(-.2,.95,side*1.65);g.add(wheel)}
 g.userData={enemy,hull:100,maxHull:100,speed:0,type};return g
}
const player=makeShip();world.add(player);player.position.set(0,0,0);
const enemies=[];
function spawnEnemy(x,z,faction='Royal Navy',type='brigantine'){
 const ship=makeShip({color:faction==='Corsairs'?0x40342c:0x4c3531,sail:faction==='Corsairs'?0x8d5a39:0xd9d4bf,enemy:true,type});ship.position.set(x,0,z);ship.rotation.y=Math.atan2(-x,-z)+Math.PI;ship.userData.name=faction+' '+type;ship.userData.faction=faction;ship.userData.hull=75;ship.userData.maxHull=75;world.add(ship);enemies.push(ship);return ship
}
spawnEnemy(20,-32,'Royal Navy');spawnEnemy(-43,30,'Corsairs','sloop');
const shots=[];const particles=[];
function addShot(from,to,owner){const ball=new THREE.Mesh(new THREE.SphereGeometry(.2,8,6),mat(owner==='player'?0xffc66c:0xd66a40,.4));ball.position.copy(from);scene.add(ball);shots.push({mesh:ball,from:from.clone(),to:to.clone(),owner,t:0,life:.55})}
function addBurst(pos,color=0xe6b767){for(let i=0;i<10;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.1+Math.random()*.16,6,5),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos);scene.add(m);particles.push({mesh:m,vel:new THREE.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5),life:.65})}}
function makeTornado(x,z){const g=new THREE.Group();g.position.set(x,0,z);for(let i=0;i<8;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(1.2+i*.18,.22,6,18),new THREE.MeshStandardMaterial({color:0x91a9a7,transparent:true,opacity:.62,roughness:.8}));ring.position.y=i*1.2;ring.scale.x=1+.2*Math.sin(i);g.add(ring)}world.add(g);return g}
const waterspout=makeTornado(-76,-63);
const stormClouds=new THREE.Group();for(let i=0;i<22;i++){const c=new THREE.Mesh(new THREE.SphereGeometry(3+Math.random()*3,8,6),mat(0x687a80));c.position.set((Math.random()-.5)*35,18+Math.random()*7,(Math.random()-.5)*28);c.scale.y=.48;stormClouds.add(c)}stormClouds.position.set(82,0,-10);world.add(stormClouds);
const lightning=new THREE.PointLight(0xc6d8ff,0,85,2);lightning.position.set(82,16,-10);scene.add(lightning);
const skyDome=new THREE.Mesh(new THREE.SphereGeometry(480,20,12),new THREE.MeshBasicMaterial({color:0x9dc6bf,side:THREE.BackSide}));scene.add(skyDome);
const state={gold:240,wood:35,renown:12,hull:86,sails:100,speed:0,heading:0,ammo:5,reload:0,weapon:'Iron Cannons',hullType:'Brigantine',faction:'Free Captain',storm:false,paused:false,nearPort:null,quest:false,gameOver:false,fullSail:false};
let clock=new THREE.Clock(),toastTimer=0,lightTimer=0,portOpen=false;
const el=id=>document.getElementById(id);
function toast(msg){const t=el('toast');t.textContent=msg;t.classList.add('show');toastTimer=2.7}
function log(msg){const box=el('log-lines'),p=document.createElement('p');p.innerHTML=`<b>${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</b> ${msg}`;box.prepend(p);while(box.children.length>3)box.lastChild.remove()}
function setStorm(on){state.storm=on;document.body.classList.toggle('storm',on);el('weather-label').textContent=on?'SQUALL WARNING':'TRADE WINDS';el('sea-state').textContent=on?'ROUGH':'CALM';scene.fog.color.setHex(on?0x4d626a:0x80b5b8);scene.fog.density=on?.009:.0068;sun.intensity=on?1.15:3.2;}
let stormClock=48;

